#include <iostream>
#include <vector>

bool clampTo(int& v, int lo, int hi)
{
    if (v < lo) { v = lo; return true; }
    if (v > hi) { v = hi; return true; }
    return false;
}

int main()
{
    int lo{}, hi{}, n{};
    if (!(std::cin >> lo >> hi >> n)) return 0;

    std::vector<int> v;
    for (int i = 0; i < n; ++i)
    {
        int x{};
        std::cin >> x;
        v.push_back(x);
    }

    int changed{};
    for (int& x : v)
        if (clampTo(x, lo, hi)) ++changed;

    bool first{ true };
    for (int x : v)
    {
        if (!first) std::cout << ' ';
        std::cout << x;
        first = false;
    }
    std::cout << "\n";

    std::cout << "changed " << changed << "\n";

    return 0;
}
